// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('image export dialog shows inline error state when the export fails', async ({ page }) => {
    test.setTimeout(100000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(baseUrl);
    await page.waitForLoadState('networkidle');
    await page.locator('[data-testid="toolbar-rectangle"]').waitFor({ state: 'visible', timeout: 10000 });
    // The toolbar radio is visually hidden and its icon subtree intercepts pointer
    // events, so select the rectangle tool via its keyboard shortcut.
    await page.keyboard.press("r");
    await page.mouse.move(500, 300);
    await page.mouse.down();
    await page.mouse.move(750, 470, { steps: 10 });
    await page.mouse.up();
    await page.keyboard.press("Control+Shift+E");
    await expect(page.getByRole("heading", { name: "Export image" }).last()).toBeVisible();
    // Let the dialog (and its canvas preview) finish rendering before the export
    // pipeline is broken, so only the export click itself fails.
    await page.getByRole("button", { name: "Export to PNG" }).waitFor({ state: 'visible', timeout: 10000 });
    await page.evaluate(() => {
  // Simulate the large/complex-canvas export failure this PR targets:
  // canvas -> blob conversion yields no blob, which Excalidraw surfaces as
  // CANVAS_POSSIBLY_TOO_BIG ("Canvas too big").
  HTMLCanvasElement.prototype.toBlob = function (cb) { cb(null); };
  return 'canvas export forced to fail';
});
    await page.getByRole("button", { name: "Export to PNG" }).click();
    // The export above genuinely fails (CANVAS_POSSIBLY_TOO_BIG). This PR is
    // supposed to replace the export buttons with an inline error + retry.
    await expect(page.getByTestId("export-error-state")).toBeVisible();
    await expect(page.getByRole("button", { name: "Try again" })).toBeVisible();
    await expect(page.getByRole("button", { name: "Export to PNG" })).toHaveCount(0);
});
